def transform(grid):
    """Extend bottom-up vertical rays through the gaps in horizontal bars."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Vertical rays are the colored cells reaching the bottom edge.
    for c in range(w):
        stem_color = grid[h - 1][c]
        if stem_color == 0:
            continue

        # A crossing is either a cell in a horizontal bar or a gap within
        # that bar. Mark rows containing a horizontal segment (length >= 2).
        crossings = []
        for r in range(h):
            color = grid[r][c]
            if color:
                # Input horizontal bars contain adjacent same-colored cells;
                # ignore isolated cells from vertical marker lines.
                left_run = c > 0 and grid[r][c - 1] == color
                right_run = c + 1 < w and grid[r][c + 1] == color
                if left_run or right_run:
                    crossings.append((r, color))
                continue
            left = next((grid[r][x] for x in range(c - 1, -1, -1) if grid[r][x]), 0)
            right = next((grid[r][x] for x in range(c + 1, w) if grid[r][x]), 0)
            if left and left == right:
                crossings.append((r, left))

        if not crossings:
            # No bar intersects this ray; simply extend the stem to the top.
            for r in range(h):
                if out[r][c] == 0:
                    out[r][c] = stem_color
            continue

        # The lowest stem color extends up to the lowest bar. Each bar color
        # then extends upward until the next bar above it.
        crossings.sort()
        lowest_r = crossings[-1][0]
        for r in range(lowest_r + 1, h):
            if out[r][c] == 0:
                out[r][c] = stem_color

        for i, (r, color) in enumerate(crossings):
            out[r][c] = color
            upper_r = crossings[i - 1][0] if i > 0 else -1
            for y in range(upper_r + 1, r):
                if out[y][c] == 0:
                    out[y][c] = color

    return out

